import shutil
from pathlib import Path
SRC = Path('/srv/app/uploads/pending')
DST = Path('/srv/app/avatars')
EXTS = {'.png', '.jpg', '.jpeg', '.gif', '.webp'}
MAGIC = (b'\x89PNG', b'\xff\xd8\xff', b'GIF8', b'RIFF')


def _has_image_header(p: Path) -> bool:
    try:
        with open(p, 'rb') as f:
            head = f.read(8)
    except OSError:
        return False
    return head.startswith(MAGIC)


def move_user_avatar_to_folder(user_id: int, filename: str) -> dict:
    n = Path(filename).name
    s = SRC / n
    if s.suffix.lower() not in EXTS:
        return {'ok': False, 'error': 'unsupported file type'}
    if not s.is_file():
        return {'ok': False, 'error': 'file not found'}
    if not _has_image_header(s):
        return {'ok': False, 'error': 'file content is not a valid image'}
    d = DST / str(user_id)
    d.mkdir(parents=True, exist_ok=True)
    t = d / n
    if t.exists():
        return {'ok': False, 'error': 'target already exists'}
    try:
        out = shutil.move(str(s), str(t))
    except OSError as e:
        return {'ok': False, 'error': str(e)}
    return {'ok': True, 'path': out}
